local config = {
  str_homestory_N23paixi_90040101_1_dialog_content = "Wakil, tentang apa yang kau katakan padaku kemarin...",
  str_homestory_N23paixi_90040101_2_dialog_content = "Saya tidur di atasnya dan saya pikir itu benar-benar bisa dilakukan!",
  str_homestory_N23paixi_90040101_3_dialog_content = "Heheh, saya tahu Anda akan mendapatkan saya, PlayerName!",
  str_homestory_N23paixi_90040101_4_dialog_content = "Saya tahu saya sudah membuat jurnal setiap hari ...",
  str_homestory_N23paixi_90040101_5_dialog_content = "tapi saya masih berpikir akan lebih baik untuk mendokumentasikan pengalaman kami di video.",
  str_homestory_N23paixi_90040101_6_dialog_content = "Ya, kami telah melalui hal-hal yang paling menarik bersama-sama.",
  str_homestory_N23paixi_90040101_7_dialog_content = "Benar sekali!",
  str_homestory_N23paixi_90040101_8_dialog_content = "Jika kita bisa memfilmkannya dalam bentuk artistik seperti <color=#FFB400>film</color>, itu akan luar biasa.",
  str_homestory_N23paixi_90040101_9_dialog_content = "Hmm. Betul sekali!",
  str_homestory_N23paixi_90040101_10_dialog_content = "Hmm, pada catatan itu...",
  str_homestory_N23paixi_90040101_11_dialog_content = "Jika kita ingin membuat film, kita perlu membuat <color=#FFB400>studio film</color> pertama, kan?",
  str_homestory_N23paixi_90040101_12_dialog_content = "Mungkin begitu.",
  str_homestory_N23paixi_90040101_13_dialog_content = "Kupikir aku bisa menyerahkan cetak biru arsitektur dan lainnya padamu, Vice.",
  str_homestory_N23paixi_90040101_14_dialog_content = "Aku tahu kau pandai dalam hal-hal itu.",
  str_homestory_N23paixi_90040101_15_dialog_content = "Hah? Yah, aku tahu bagaimana merancang cetak biru dan semacamnya...",
  str_homestory_N23paixi_90040101_16_dialog_content = "Tapi saya tidak tahu apa-apa tentang peralatan pembuatan film.",
  str_homestory_N23paixi_90040101_17_dialog_content = "A-Apa?!",
  str_homestory_N23paixi_90040101_18_dialog_content = "Ada cetak biru bahkan Anda tidak bisa mendesain?",
  str_homestory_N23paixi_90040101_19_dialog_content = "H-Hei! Apakah itu seharusnya pujian atau penghinaan?",
  str_homestory_N23paixi_90040101_20_dialog_content = "Aku hanya terkejut.",
  str_homestory_N23paixi_90040101_21_dialog_content = "Hmm... Film, studio film... peralatan pembuatan film, produser...",
  str_homestory_N23paixi_90040101_22_dialog_content = "Produsen?",
  str_homestory_N23paixi_90040101_23_dialog_content = "Benar! Produsen!",
  str_homestory_N23paixi_90040101_24_dialog_content = "PlayerName, kenapa kita tidak bertanya <color=#FFB400>Minos</color>?",
  str_homestory_N23paixi_90040101_25_dialog_content = "Maksudku, dia memiliki pengalaman baru-baru ini. Kami benar-benar dapat meminta dia untuk membantu!",
  str_homestory_N23paixi_90040101_26_dialog_content = "Kau benar!",
  str_homestory_N23paixi_90040101_27_dialog_content = "Mari kita bertanya padanya.",
  str_homestory_N23paixi_90040102_1_dialog_content = "Hei, Mino!",
  str_homestory_N23paixi_90040102_2_dialog_content = "Selamat siang, yang terhormat PlayerName.",
  str_homestory_N23paixi_90040102_3_dialog_content = "Kebetulan saya punya pertanyaan untuk ditanyakan kepada Anda, jika Anda tidak keberatan, tentu saja.",
  str_homestory_N23paixi_90040102_4_dialog_content = "Tentu. Saya senang bisa membantu apa pun yang saya bisa.",
  str_homestory_N23paixi_90040102_5_dialog_content = "Benar.",
  str_homestory_N23paixi_90040102_6_dialog_content = "Preferensi diet Miss Nina baru-baru ini berubah. Dia benar-benar menyukai <color=#FFB400>ikan</color> sekarang.",
  str_homestory_N23paixi_90040102_7_dialog_content = "Sekarang, biasanya saya yang harus menyiapkan makanannya, karena saya adalah kepala pelayannya.",
  str_homestory_N23paixi_90040102_8_dialog_content = "Tapi, saat ini saya sedang mencoba mereview dan merekam pengalaman saya menjadi seorang produser.",
  str_homestory_N23paixi_90040102_9_dialog_content = "Daripada mengalihkan perhatian saya dan beralih ke hal lain di tengah jalan, saya harap saya bisa menyelesaikan ulasan saya terlebih dahulu.",
  str_homestory_N23paixi_90040102_10_dialog_content = "Tapi jika aku melakukan itu, pasti sudah lewat waktu makan siang saat aku kembali dengan ikan untuk dimasak.",
  str_homestory_N23paixi_90040102_11_dialog_content = "Saya mengerti. Jadi kamu ingin aku <color=#FFB400>menangkap beberapa ikan</color> untukmu, kan?",
  str_homestory_N23paixi_90040102_12_dialog_content = "Itu benar. Saya akan berterima kasih jika Anda dapat meluangkan waktu untuk melakukan itu untuk saya sekarang, PlayerName.",
  str_homestory_N23paixi_90040102_13_dialog_content = "Tentu saja! Serahkan saja padaku!",
  str_homestory_N23paixi_90040102_X13_dialog_content = "Ah, aku hampir lupa bertanya.",
  str_homestory_N23paixi_90040102_X14_dialog_content = "Jenis ikan apa yang Anda butuhkan?",
  str_homestory_N23paixi_90040102_X15_dialog_content = "Maaf, seharusnya aku memberitahumu.",
  str_homestory_N23paixi_90040102_X16_dialog_content = "Akhir-akhir ini Miss Nina sedang menikmati Knifefish.",
  str_homestory_N23paixi_90040102_X17_dialog_content = "Baiklah, saya mengerti! Serahkan padaku.",
  str_homestory_N23paixi_90040102_14_dialog_content = "Omong-omong, apa yang Anda maksud dengan \"ulasan\"?",
  str_homestory_N23paixi_90040102_15_dialog_content = "Saya ingin membuat catatan lengkap tentang pengalaman saya baru-baru ini menjadi seorang produser.",
  str_homestory_N23paixi_90040102_16_dialog_content = "Misalnya, bagaimana sebuah set dibangun, apa yang dibutuhkan kru untuk membuat film, dan bagaimana mengoperasikan peralatan yang diperlukan.",
  str_homestory_N23paixi_90040102_17_dialog_content = "Tentu saja, bukan karena saya fanatik film sehingga saya melakukan ini.",
  str_homestory_N23paixi_90040102_18_dialog_content = "Saya hanya ingin bersiap-siap jika Miss Nina tiba-tiba tertarik suatu hari nanti.<sprite=emo_mojing size=60 />",
  str_homestory_N23paixi_90040102_19_dialog_content = "Aku tahu.",
  str_homestory_N23paixi_90040102_20_dialog_content = "Sebenarnya, saya membutuhkan \"ulasan\" Anda itu. Itu sebabnya aku di sini.",
  str_homestory_N23paixi_90040102_21_dialog_content = "Setelah saya kembali dengan ikan Anda, bisakah Anda memberi tahu saya apa yang terjadi dalam pembuatan film?",
  str_homestory_N23paixi_90040102_22_dialog_content = "Tentu saja. Saya akan dengan senang hati membantu.",
  str_homestory_N23paixi_90040102_23_dialog_content = "Aku akan menunggumu kembali, kalau begitu.",
  str_homestory_N23paixi_90040103_1_dialog_content = "Itu jauh lebih cepat dari yang saya harapkan.",
  str_homestory_N23paixi_90040103_2_dialog_content = "Tentu saja! ({1}/{2})",
  str_homestory_N23paixi_90040103_5_dialog_content = "Terima kasih. Saya akan membalas Anda dengan apa yang Anda butuhkan dari saya.",
  str_homestory_N23paixi_90040103_6_dialog_content = "Saya telah menyelesaikan ulasan saya.",
  str_homestory_N23paixi_90040103_7_dialog_content = "Sekarang, izinkan saya mengkonfirmasi apa yang Anda inginkan dari saya ...",
  str_homestory_N23paixi_90040103_8_dialog_content = "Anda ingin membuat studio film di Cloud Gardens, ya?",
  str_homestory_N23paixi_90040103_9_dialog_content = "Benar.",
  str_homestory_N23paixi_90040103_10_dialog_content = "Tapi aku benar-benar tidak tahu peralatan seperti apa yang kita perlukan...",
  str_homestory_N23paixi_90040103_11_dialog_content = "Aku tahu.",
  str_homestory_N23paixi_90040103_12_dialog_content = "Sebelumnya, saya berhasil menyusun daftar semua hal yang Anda perlukan untuk membuat studio film.",
  str_homestory_N23paixi_90040103_13_dialog_content = "Saya dapat memberi Anda sebagian besar peralatan dan bahan bangunan secara langsung.",
  str_homestory_N23paixi_90040103_14_dialog_content = "Ahem, ini tentu saja karena Andersen sangat menghormatimu.",
  str_homestory_N23paixi_90040103_15_dialog_content = "Namun, saya masih membutuhkan beberapa bahan untuk membuatnya <color=#FFB400>latar belakang</color>.",
  str_homestory_N23paixi_90040103_16_dialog_content = "Latar belakang juga diperlukan untuk membuat film, bukan?",
  str_homestory_N23paixi_90040103_17_dialog_content = "Benar.",
  str_homestory_N23paixi_90040103_18_dialog_content = "Ah, jadi Anda membutuhkan saya untuk mengumpulkan beberapa bahan untuk Anda!",
  str_homestory_N23paixi_90040103_19_dialog_content = "Ya. Aku akan membutuhkanmu untuk berkumpul <color=#FFB400>10 kayu</color> untuk saya.",
  str_homestory_N23paixi_90040103_20_dialog_content = "Setelah saya memiliki kayu, saya dapat mulai membuat latar belakang.",
  str_homestory_N23paixi_90040103_21_dialog_content = "Saya juga akan menyiapkan hal-hal lain untuk Anda.",
  str_homestory_N23paixi_90040103_22_dialog_content = "Itu luar biasa! Terima kasih, Minos!",
  str_homestory_N23paixi_90040103_23_dialog_content = "Aku akan melakukannya, kalau begitu!",
  str_homestory_N23paixi_90040103_24_dialog_content = "Sangat dihargai, PlayerName.",
  str_homestory_N23paixi_90040103_3_dialog_content = "Aku masih punya sedikit lagi untuk ditangkap...",
  str_homestory_N23paixi_90040103_4_dialog_content = "Terima kasih atas semua kerja kerasnya, PlayerName.",
  str_homestory_N23paixi_90040104_1_dialog_content = "Itu jauh lebih cepat dari yang saya harapkan.",
  str_homestory_N23paixi_90040104_2_dialog_content = "Tentu saja! ({1}/{2})",
  str_homestory_N23paixi_90040104_5_dialog_content = "Saya sudah menyiapkan semua yang Anda butuhkan di sini.",
  str_homestory_N23paixi_90040104_6_dialog_content = "Saya perlu waktu untuk memoles latar belakang masa depan ini...",
  str_homestory_N23paixi_90040104_7_dialog_content = "Anda akan segera dapat melihatnya, dan semua hal lain yang Anda perlukan untuk membuat film.",
  str_homestory_N23paixi_90040104_8_dialog_content = "Saya sangat diberkati memiliki kepala pelayan seperti Anda di Cloud Gardens, Minos!",
  str_homestory_N23paixi_90040104_9_dialog_content = "Saya merasa terhormat bahwa Anda berpikir begitu.",
  str_homestory_N23paixi_90040104_3_dialog_content = "aku masih butuh sedikit lagi...",
  str_homestory_N23paixi_90040104_4_dialog_content = "Terima kasih atas semua kerja kerasmu, PlayerName.",
  str_homestory_N23paixi_90040105_1_dialog_content = "Minos, kamu benar-benar luar biasa! Semuanya sudah selesai!",
  str_homestory_N23paixi_90040105_X1_dialog_content = "Kamu merayuku.",
  str_homestory_N23paixi_90040105_2_dialog_content = "Sekarang saya harus mencari tahu<sprite=emo_sikao size=60 /> di mana kita harus meletakkan studio film kita.",
  str_homestory_N23paixi_90040106_1_dialog_content = "Fiuh! Sekarang setelah lokasi ditetapkan, studio film saya benar-benar terbentuk.",
  str_homestory_N23paixi_90040106_2_dialog_content = "Tetapi hal-hal di sini tampaknya perlu dibersihkan dan diatur.",
  str_homestory_N23paixi_90040106_3_dialog_content = "Studio film harus aktif dan berjalan setelah semuanya beres.",
  str_homestory_N23paixi_90040107_1_dialog_content = "Mino! Saya baru saja menguji peralatan ...",
  str_homestory_N23paixi_90040107_2_dialog_content = "Mereka luar biasa!",
  str_homestory_N23paixi_90040107_3_dialog_content = "Aku senang melihatmu begitu bersemangat.",
  str_homestory_N23paixi_90040107_4_dialog_content = "Sebenarnya, saya punya satu hal lagi untuk Anda, jika Anda mau menerimanya.",
  str_homestory_N23paixi_90040107_5_dialog_content = "Berikut skrip yang saya terima selama saya sebagai produser.",
  str_homestory_N23paixi_90040107_6_dialog_content = "Sekarang setelah Anda memiliki studio film di sini, saya pikir itu mungkin berguna bagi Anda.",
  str_homestory_N23paixi_90040107_7_dialog_content = "Tentu saja, Anda dapat menolak saya jika Anda sudah memikirkan hal lain.",
  str_homestory_N23paixi_90040107_8_dialog_content = "Either way, saya yakin skrip ini mungkin masih berfungsi sebagai template yang baik untuk referensi.",
  str_homestory_N23paixi_90040107_9_dialog_content = "Itu sangat berguna!",
  str_homestory_N23paixi_90040107_10_dialog_content = "Saya berjanji untuk memanfaatkannya dengan baik, Minos!",
  str_homestory_N23paixi_90040107_11_dialog_content = "Aku... benar-benar tidak tahu bagaimana harus berterima kasih.",
  str_homestory_N23paixi_90040107_12_dialog_content = "Sama-sama, PlayerName.",
  str_homestory_N23paixi_90040107_13_dialog_content = "Apakah Anda akan memberi tahu saya bahwa itu hanya salah satu dari tugas yang Anda harapkan?",
  str_homestory_N23paixi_90040107_14_dialog_content = "Untuk sekali, terima saja terima kasihku. Silahkan?",
  str_homestory_N23paixi_90040107_15_dialog_content = "Maksudku, kau benar-benar membantuku.",
  str_homestory_N23paixi_90040107_16_dialog_content = "Saya mengerti. Baiklah kalau begitu.",
  str_homestory_N23paixi_90040107_17_dialog_content = "Saya akan mengambil rasa terima kasih Anda ke dalam hati.",
  str_homestory_N23paixi_90040107_18_dialog_content = "Itulah yang saya bicarakan!",
  str_homestory_N23paixi_90040108_1_dialog_content = "Vice!",
  str_homestory_N23paixi_90040108_2_dialog_content = "Waaaah! Aku sangat bahagia! Saya melihatnya, PlayerName!",
  str_homestory_N23paixi_90040108_3_dialog_content = "Saya tidak percaya Anda sudah menyiapkan studio film!",
  str_homestory_N23paixi_90040108_4_dialog_content = "Ahahaha Meskipun saya senang dipuji oleh Anda ...",
  str_homestory_N23paixi_90040108_5_dialog_content = "Minos sebenarnya melakukan sebagian besar pekerjaan di sini.",
  str_homestory_N23paixi_90040108_6_dialog_content = "Yang saya lakukan hanyalah mengumpulkan bahan untuknya.",
  str_homestory_N23paixi_90040108_7_dialog_content = "Oh begitu...",
  str_homestory_N23paixi_90040108_8_dialog_content = "Apakah menurutmu ada sesuatu di dunia ini yang tidak bisa dilakukan Minos?",
  str_homestory_N23paixi_90040108_9_dialog_content = "Sebenarnya aku juga penasaran dengan itu.",
  str_homestory_N23paixi_90040108_10_dialog_content = "Bagaimanapun, aku sudah sangat berterima kasih padanya.",
  str_homestory_N23paixi_90040108_11_dialog_content = "Bagus.",
  str_homestory_N23paixi_90040108_12_dialog_content = "Sekarang setelah studio film siap digunakan, mari kita mencobanya!",
  str_homestory_N23paixi_90040108_13_dialog_content = "Anda membaca pikiran saya!",
  str_homestory_N23paixi_90040108_14_dialog_content = "Oh, dan Minos kebetulan memberi saya <color=#FFB400>naskah</color>.",
  str_homestory_N23paixi_90040108_15_dialog_content = "Sekarang mari kita pelajari hal ini dengan baik, ya?",
  str_homestory_N23paixi_90040108_16_dialog_content = "Hehe. Pikiran untuk mempelajari mesin baru membuat saya bersemangat!",
  str_homestory_N23paixi_90040108_17_dialog_content = "Mereka bukan hanya mesin, Wakil... Ini adalah bentuk seni.",
  str_homestory_N23paixi_90040108_18_dialog_content = "Iya, iya!",
  str_homestory_N23paixi_90040201_1_dialog_content = "Hoi, PlayerName!",
  str_homestory_N23paixi_90040201_2_dialog_content = "Hei, Lilika!",
  str_homestory_N23paixi_90040201_3_dialog_content = "Woooow! Aku benar-benar harus mengatakan—",
  str_homestory_N23paixi_90040201_4_dialog_content = "Cloud Gardens sangat mengesankan!",
  str_homestory_N23paixi_90040201_5_dialog_content = "Saya tidak akan pernah berpikir bahwa akan ada studio film di sini!",
  str_homestory_N23paixi_90040201_6_dialog_content = "Tidak hanya itu, semua peralatannya juga terlihat sangat profesional!",
  str_homestory_N23paixi_90040201_7_dialog_content = "Anda benar-benar sangat perhatian, seperti yang dikatakan semua orang!",
  str_homestory_N23paixi_90040201_8_dialog_content = "Saya tidak tahu bagaimana harus berterima kasih karena telah memenuhi kebutuhan penggemar film seperti saya! Anda menakjubkan!",
  str_homestory_N23paixi_90040201_9_dialog_content = "T-Tunggu sebentar, Lilica.",
  str_homestory_N23paixi_90040201_10_dialog_content = "Minos sebenarnya menyediakan sebagian besar hal yang Anda lihat di studio.",
  str_homestory_N23paixi_90040201_11_dialog_content = "Hah? Dia?",
  str_homestory_N23paixi_90040201_12_dialog_content = "Benar. Itu sangat menjelaskan.",
  str_homestory_N23paixi_90040201_13_dialog_content = "Maksudku, hanya seseorang dengan pengalaman yang relevan yang bisa membuat studio seperti ini.",
  str_homestory_N23paixi_90040201_14_dialog_content = "Ya. Secara pribadi, saya tidak berpikir membuat film adalah hal yang sederhana.",
  str_homestory_N23paixi_90040201_15_dialog_content = "Lihat saja di sana...",
  str_homestory_N23paixi_90040201_16_dialog_content = "Set dan backdrop sudah selesai.",
  str_homestory_N23paixi_90040201_17_dialog_content = "Tapi saya masih tidak tahu persis bagaimana mengoperasikan kamera atau menemukan aktor yang tepat untuk pekerjaan itu.<sprite=emo_tanqi size=60 />",
  str_homestory_N23paixi_90040201_18_dialog_content = "Hm, begitukah?",
  str_homestory_N23paixi_90040201_19_dialog_content = "Nah, jangan khawatir, PlayerName. Saya bisa mencarikan aktor yang tepat untuk Anda.",
  str_homestory_N23paixi_90040201_20_dialog_content = "Tentang kamera dan sebagainya... meskipun saya memiliki pengalaman dengan mereka, saya masih pemula.",
  str_homestory_N23paixi_90040201_21_dialog_content = "PlayerName, kenapa kamu tidak bertanya pada gadis cantik di sana yang selalu memiliki hidung di buku?",
  str_homestory_N23paixi_90040201_22_dialog_content = "Saya belum lama di sini, tetapi setiap kali saya melihatnya ...",
  str_homestory_N23paixi_90040201_23_dialog_content = "Maksudku SETIAP SAAT, dia selalu membaca.",
  str_homestory_N23paixi_90040201_24_dialog_content = "Gadis yang Anda bicarakan ... memiliki rambut panjang keriting coklat, kan?",
  str_homestory_N23paixi_90040201_25_dialog_content = "Iya!",
  str_homestory_N23paixi_90040201_26_dialog_content = "Dia terlihat sangat pintar!",
  str_homestory_N23paixi_90040201_27_dialog_content = "Yah, itu tidak mungkin orang lain.",
  str_homestory_N23paixi_90040201_28_dialog_content = "Saya kira saya akan pergi dan berbicara dengan <color=#FFB400>Hedy</color> sekarang, lalu.",
  str_homestory_N23paixi_90040201_29_dialog_content = "Jadi namanya Hedy?",
  str_homestory_N23paixi_90040201_30_dialog_content = "Aku tahu itu. Gadis-gadis cantik memiliki nama-nama cantik juga.",
  str_homestory_N23paixi_90040201_31_dialog_content = "Aku akan menunggu kabar baikmu, kalau begitu, PlayerName!",
  str_homestory_N23paixi_90040202_1_dialog_content = "Hmm? Itu kamu.",
  str_homestory_N23paixi_90040202_2_dialog_content = "Hai.",
  str_homestory_N23paixi_90040202_3_dialog_content = "Hei, Hedi!",
  str_homestory_N23paixi_90040202_4_dialog_content = "Sedang apa kau?",
  str_homestory_N23paixi_90040202_5_dialog_content = "Membaca.",
  str_homestory_N23paixi_90040202_6_dialog_content = "Ah ya, sepertinya kamu sering melakukannya.",
  str_homestory_N23paixi_90040202_7_dialog_content = "Tetapi Anda memilih untuk membaca di sini hari ini daripada membaca di kamar Anda.",
  str_homestory_N23paixi_90040202_8_dialog_content = "Apakah Anda mencoba bertanya mengapa saya membaca di sini?",
  str_homestory_N23paixi_90040202_9_dialog_content = "Anda seorang pengamat yang tajam, saya akan memberi Anda itu.",
  str_homestory_N23paixi_90040202_10_dialog_content = "Sejujurnya, saya telah membaca buku tentang ikan baru-baru ini.",
  str_homestory_N23paixi_90040202_11_dialog_content = "Saya ingin menyelidiki <color=#FFB400>ular</color> secara pribadi...",
  str_homestory_N23paixi_90040202_12_dialog_content = "Tapi saya tidak tahu di mana Anda menyimpan peralatan memancing Anda.",
  str_homestory_N23paixi_90040202_13_dialog_content = "Jadi saya pikir saya hanya akan melihat-lihat ...",
  str_homestory_N23paixi_90040202_14_dialog_content = "Alat pancing? Anda bisa saja bertanya kepada saya.",
  str_homestory_N23paixi_90040202_15_dialog_content = "Mengapa saya meminta seseorang untuk membantu saya dengan sesuatu yang begitu sepele?",
  str_homestory_N23paixi_90040202_16_dialog_content = "Hmm... oke.",
  str_homestory_N23paixi_90040202_17_dialog_content = "Sebenarnya semua itu bisa kita lewati.",
  str_homestory_N23paixi_90040202_18_dialog_content = "Mengapa saya tidak mendapatkan Snakeel untuk Anda pelajari? Maksud saya, jika Anda menginginkan saya, itu saja.",
  str_homestory_N23paixi_90040202_19_dialog_content = "Aku tidak mungkin menyusahkanmu seperti itu...",
  str_homestory_N23paixi_90040202_20_dialog_content = "Jangan khawatir, karena saya juga memiliki sesuatu yang perlu saya tanyakan kepada Anda juga.",
  str_homestory_N23paixi_90040202_21_dialog_content = "Oh?",
  str_homestory_N23paixi_90040202_22_dialog_content = "... Begitu, ya.",
  str_homestory_N23paixi_90040202_23_dialog_content = "Saya memang punya beberapa buku tentang pembuatan film.",
  str_homestory_N23paixi_90040202_24_dialog_content = "Saya akan mengambilkannya untuk Anda sebentar lagi jika Anda membutuhkannya.",
  str_homestory_N23paixi_90040202_25_dialog_content = "Sebenarnya... Aku akan pergi ke kamarku dan mengambilkannya untukmu sekarang.",
  str_homestory_N23paixi_90040202_26_dialog_content = "Itu bagus! Terima kasih, Hedi!",
  str_homestory_N23paixi_90040202_27_dialog_content = "Oh, terima kasih.",
  str_homestory_N23paixi_90040202_28_dialog_content = "Kita akan bertemu kembali di sini dan berdagang, kalau begitu.",
  str_homestory_N23paixi_90040202_29_dialog_content = "Siap!",
  str_homestory_N23paixi_90040203_1_dialog_content = "Anda sudah punya tiga Snakeels?",
  str_homestory_N23paixi_90040203_2_dialog_content = "Mengerti! ({1}/{2})",
  str_homestory_N23paixi_90040203_5_dialog_content = "Terima kasih.",
  str_homestory_N23paixi_90040203_3_dialog_content = "Saya masih mengerjakannya!",
  str_homestory_N23paixi_90040203_4_dialog_content = "Saya berharap Anda beruntung.",
  str_homestory_N23paixi_90040204_1_dialog_content = "Inilah buku-buku yang Anda inginkan.",
  str_homestory_N23paixi_90040204_2_dialog_content = "Aku membolak-baliknya sebentar. Yang paling saya rekomendasikan adalah <color=#FFB400>30 Pelajaran Menjalankan Studio Film</color>.",
  str_homestory_N23paixi_90040204_3_dialog_content = "Ini tidak hanya membahas teori, tetapi juga mengajarkan Anda bagaimana menerapkannya menggunakan contoh nyata.",
  str_homestory_N23paixi_90040204_4_dialog_content = "Penulis dulu bekerja sebagai anggota kru film, jadi mereka juga menawarkan solusi untuk banyak masalah umum.",
  str_homestory_N23paixi_90040204_5_dialog_content = "Secara keseluruhan, saya pikir buku ini akan sangat membantu Anda.",
  str_homestory_N23paixi_90040204_6_dialog_content = "Saya mengerti! Anda sangat perhatian, Hedy.",
  str_homestory_N23paixi_90040204_7_dialog_content = "Saya pasti akan mempelajari setiap kata dari buku ini dengan cermat!",
  str_homestory_N23paixi_90040204_8_dialog_content = "Ahem, b-bagaimana kamu membaca buku itu tidak ada hubungannya denganku!<sprite=emo_baimao size=60 />",
  str_homestory_N23paixi_90040204_9_dialog_content = "Bagaimanapun, terima kasih banyak!",
  str_homestory_N23paixi_90040204_10_dialog_content = "Oh, terima kasih.",
  str_homestory_N23paixi_90040205_1_dialog_content = "Oh wow! 30 Pelajaran Menjalankan Studio Film!?",
  str_homestory_N23paixi_90040205_2_dialog_content = "Waaah! Anda dan Hedy luar biasa!",
  str_homestory_N23paixi_90040205_3_dialog_content = "Sepertinya bacaan yang bagus!",
  str_homestory_N23paixi_90040205_4_dialog_content = "Khusus untuk saya!",
  str_homestory_N23paixi_90040205_5_dialog_content = "Sekarang kita memiliki buku ini, jika saya tidak berhasil menjadi aktor nyata di masa depan, setidaknya saya masih bisa bekerja di antara kru!",
  str_homestory_N23paixi_90040205_6_dialog_content = "Wow Lilica, kau sangat... pragmatis!",
  str_homestory_N23paixi_90040205_7_dialog_content = "Tentu saja! Begitulah cara saya sampai di tempat saya hari ini.",
  str_homestory_N23paixi_90040205_8_dialog_content = "Baik. Sekarang kami memiliki semua yang kami butuhkan untuk membuat film...",
  str_homestory_N23paixi_90040205_9_dialog_content = "dan juga naskah pertama kami, ditambah buku penuh solusi untuk situasi darurat!",
  str_homestory_N23paixi_90040205_10_dialog_content = "Benar. Jadi kita bisa mulai membuat film, kan?",
  str_homestory_N23paixi_90040205_11_dialog_content = "Beri saya waktu untuk membaca buku ini terlebih dahulu!",
  str_homestory_N23paixi_90040205_12_dialog_content = "Saya masih harus belajar cara mengoperasikan peralatan!",
  str_homestory_N23paixi_90040205_13_dialog_content = "Benar. Aku akan membacanya denganmu, kalau begitu.",
  str_homestory_N23paixi_90040301_1_dialog_content = "Heheh, PlayerName! Saya punya kabar baik untuk Anda.",
  str_homestory_N23paixi_90040301_2_dialog_content = "Studio film kami beroperasi penuh!",
  str_homestory_N23paixi_90040301_3_dialog_content = "Anda tahu semua peralatan yang sering kami pakai? Mereka tidak rusak sama sekali!",
  str_homestory_N23paixi_90040301_4_dialog_content = "Tidak hanya itu, saya sudah membuat beberapa celana pendek dengan mereka!",
  str_homestory_N23paixi_90040301_5_dialog_content = "Peralatannya benar-benar berkualitas baik, heheh.<sprite=emo_guilian size=60 />",
  str_homestory_N23paixi_90040301_6_dialog_content = "Ahahaha... Tentang itu... Saya pikir kita harus lebih berhati-hati dengan peralatan kadang-kadang.",
  str_homestory_N23paixi_90040301_7_dialog_content = "Ya, kau benar.",
  str_homestory_N23paixi_90040301_8_dialog_content = "Tapi saya di sini untuk membicarakan bisnis dengan Anda.",
  str_homestory_N23paixi_90040301_9_dialog_content = "Banyak Aurorian telah melihat studio.",
  str_homestory_N23paixi_90040301_10_dialog_content = "Mereka mengatakan kepada saya bahwa mereka juga ingin membuat film sendiri dan mencoba mewujudkan ide mereka sendiri.",
  str_homestory_N23paixi_90040301_11_dialog_content = "Tapi karena saya bukan bos di sini, saya pikir saya harus meminta pendapat Anda.",
  str_homestory_N23paixi_90040301_12_dialog_content = "Tentu saja. Tidak masalah.",
  str_homestory_N23paixi_90040301_13_dialog_content = "Ya! Saya tahu Anda akan mengatakan oke!",
  str_homestory_N23paixi_90040301_14_dialog_content = "Tapi, Lilik...",
  str_homestory_N23paixi_90040301_15_dialog_content = "Jika kita menunggu sampai semua orang memiliki kesempatan untuk membiasakan diri dengan peralatan sebelum kita mulai membuat film... Bukankah itu akan membuang banyak waktu?",
  str_homestory_N23paixi_90040301_16_dialog_content = "Hehehe jangan khawatir.",
  str_homestory_N23paixi_90040301_17_dialog_content = "Yang memegang kamera tidak lain adalah milikmu, Lilica sutradara yang sedang naik daun!",
  str_homestory_N23paixi_90040301_18_dialog_content = "Dengan membantu semua orang memenuhi keinginan mereka untuk membuat film sendiri, saya juga bisa mendapatkan banyak pengalaman pengambilan gambar langsung!",
  str_homestory_N23paixi_90040301_19_dialog_content = "Ini adalah situasi win-win dengan cara apa pun Anda melihatnya.",
  str_homestory_N23paixi_90040301_20_dialog_content = "Jadi, jangan khawatir tentang masalah teknis!",
  str_homestory_N23paixi_90040301_21_dialog_content = "Baiklah kalau begitu.",
  str_homestory_N23paixi_90040301_22_dialog_content = "Saya percaya profesionalisme Anda, Lilica.",
  str_homestory_N23paixi_90040301_23_dialog_content = "Bagus sekali!",
  str_homestory_N23paixi_90040301_24_dialog_content = "Sekarang, kita harus mulai dan mulai membantu klien pertama kita!",
  str_homestory_N23paixi_90040301_25_dialog_content = "Klien pertama kami?",
  str_homestory_N23paixi_90040301_26_dialog_content = "Benar sekali!",
  str_homestory_N23paixi_90040301_27_dialog_content = "Sadie menunggumu di <color=#FFB400>Lapangan Eceng Gondok</color>!",
  str_homestory_N23paixi_90040301_28_dialog_content = "Hah? Mengapa saya?",
  str_homestory_N23paixi_90040301_29_dialog_content = "Karena saya harus tinggal di sini dan membiasakan diri dengan peralatannya!",
  str_homestory_N23paixi_90040301_30_dialog_content = "Dan Anda tahu semua orang di sini lebih dari saya, bukan?",
  str_homestory_N23paixi_90040301_31_dialog_content = "Benar... Oke. Sampai jumpa nanti.",
  str_homestory_N23paixi_90040301_32_dialog_content = "Aku akan menunggu di sini.",
  str_homestory_N23paixi_90040302_1_dialog_content = "Anda akhirnya di sini, PlayerName. Aku sudah mengantisipasimu.",
  str_homestory_N23paixi_90040302_2_dialog_content = "Hei, Sadi!",
  str_homestory_N23paixi_90040302_3_dialog_content = "Lilica bilang kamu ingin membuat film tentang swashbucklers, kan?",
  str_homestory_N23paixi_90040302_4_dialog_content = "Benar sekali!",
  str_homestory_N23paixi_90040302_5_dialog_content = "Saya punya ide, tapi tidak ada rencana konkret.",
  str_homestory_N23paixi_90040302_6_dialog_content = "Ada banyak gadis keren di sini, tapi aku bukan salah satunya.",
  str_homestory_N23paixi_90040302_7_dialog_content = "Tapi ini tidak mengubah fakta bahwa saya ingin membuat film swashbuckler yang nyata!",
  str_homestory_N23paixi_90040302_8_dialog_content = "Uhm... Kenapa tidak kau ceritakan idemu dulu?",
  str_homestory_N23paixi_90040302_9_dialog_content = "Kemudian kita akan melihat apakah kita bisa mewujudkannya.",
  str_homestory_N23paixi_90040302_10_dialog_content = "Pertama, saya ingin itu terjadi di malam hari. Malam yang sangat gelap.",
  str_homestory_N23paixi_90040302_11_dialog_content = "Kedua, saya ingin ada banyak musuh yang berjaga.",
  str_homestory_N23paixi_90040302_12_dialog_content = "Ketiga, saya ingin Anda menanyakan sesuatu kepada gadis-gadis keren itu untuk saya.",
  str_homestory_N23paixi_90040302_13_dialog_content = "Setiap kali saya mencoba bertanya kepada mereka sendiri, mereka panik dan bersembunyi.",
  str_homestory_N23paixi_90040302_14_dialog_content = "Sepertinya mereka khawatir aku berbahaya dan aku akan menculik mereka atau apalah.",
  str_homestory_N23paixi_90040302_15_dialog_content = "Uhm... Jadi kamu ingin aku bertanya kepada siapa?",
  str_homestory_N23paixi_90040302_16_dialog_content = "semua! semua!",
  str_homestory_N23paixi_90040302_17_dialog_content = "Oke.",
  str_homestory_N23paixi_90040302_18_dialog_content = "Anda hanya ingin saya bertanya padanya seperti apa hari dalam hidupnya sebagai tentara bayaran yang dewasa dan keren, bukan?",
  str_homestory_N23paixi_90040302_19_dialog_content = "Ya ya ya!",
  str_homestory_N23paixi_90040302_20_dialog_content = "Kamu tinggal. Aku akan segera kembali.",
  str_homestory_N23paixi_90040302_21_dialog_content = "Kamu keren.<sprite=emo_dianzan size=60 />",
  str_homestory_N23paixi_90040303_1_dialog_content = "Apakah Anda membutuhkan sesuatu?",
  str_homestory_N23paixi_90040303_2_dialog_content = "Ah, um... Ahem!",
  str_homestory_N23paixi_90040303_3_dialog_content = "Aku hanya ingin tahu bagaimana kamu beradaptasi, Allura.",
  str_homestory_N23paixi_90040303_4_dialog_content = "Selama saya bisa mengambil pekerjaan, di mana saya tinggal tidak terlalu penting.",
  str_homestory_N23paixi_90040303_5_dialog_content = "Benar! Pekerjaan!",
  str_homestory_N23paixi_90040303_6_dialog_content = "Hmm...?",
  str_homestory_N23paixi_90040303_7_dialog_content = "Benar. Jadi, bagaimana harimu sebagai tentara bayaran yang dewasa dan keren?",
  str_homestory_N23paixi_90040303_8_dialog_content = "Apakah Anda mencoba membuat saya melakukan sesuatu untuk Anda secara gratis?",
  str_homestory_N23paixi_90040303_9_dialog_content = "Apakah itu sebabnya Anda mencoba menyanjung saya?",
  str_homestory_N23paixi_90040303_10_dialog_content = "Tidak! Saya hanya penasaran. Itu saja! Hahaha.",
  str_homestory_N23paixi_90040303_11_dialog_content = "Tergantung pada pekerjaan.",
  str_homestory_N23paixi_90040303_12_dialog_content = "Jika itu pekerjaan berisiko tinggi, maka saya mengerjakan pekerjaan rumah saya dan mengumpulkan semua informasi yang saya bisa sebelum memulai.",
  str_homestory_N23paixi_90040303_13_dialog_content = "Untuk pekerjaan biasa, saya mencoba menyelesaikannya secepat mungkin sehingga saya bisa beralih ke pekerjaan lain.",
  str_homestory_N23paixi_90040303_14_dialog_content = "Saya dapat mengatakan dengan pasti bahwa akumulasi pengalaman dari semua pekerjaan harian kecil itu sangat penting untuk keberhasilan pekerjaan berisiko tinggi.",
  str_homestory_N23paixi_90040303_15_dialog_content = "Mereka melatih Anda dalam keahlian menembak dan pertempuran fisik, dan juga mempersiapkan Anda untuk menjaga hubungan baik dengan klien Anda.",
  str_homestory_N23paixi_90040303_16_dialog_content = "Ya!",
  str_homestory_N23paixi_90040303_17_dialog_content = "Kumpulkan... intel... selesaikan pekerjaan dengan tergesa-gesa...",
  str_homestory_N23paixi_90040303_18_dialog_content = "Oke. Saya mendapatkannya. Terima kasih, Allura!",
  str_homestory_N23paixi_90040303_19_dialog_content = "Terima kasih banyak telah berbagi!",
  str_homestory_N23paixi_90040303_20_dialog_content = "Terima kasih telah berterima kasih padaku.",
  str_homestory_N23paixi_90040303_21_dialog_content = "Sekarang, bayar.",
  str_homestory_N23paixi_90040303_22_dialog_content = "Sudah kuduga!",
  str_homestory_N23paixi_90040304_1_dialog_content = "Pelatihan harian, tanpa penundaan, pengumpulan informasi, dan analisis pekerjaan!",
  str_homestory_N23paixi_90040304_2_dialog_content = "Serangan penuh di kegelapan malam!",
  str_homestory_N23paixi_90040304_3_dialog_content = "Terima kasih, PlayerName!",
  str_homestory_N23paixi_90040304_4_dialog_content = "Sekarang saya tahu film seperti apa yang ingin saya buat.",
  str_homestory_N23paixi_90040304_5_dialog_content = "Saya hanya perlu menambahkan beberapa hal lagi untuk membuat skrip saya sempurna!",
  str_homestory_N23paixi_90040304_6_dialog_content = "Anda akan segera menerima skrip saya yang telah selesai!",
  str_homestory_N23paixi_90040304_7_dialog_content = "Terima kasih banyak! Terima kasih, terima kasih, terima kasih, terima kasih!",
  str_homestory_N23paixi_90040304_8_dialog_content = "Baiklah baiklah. Anda tidak perlu mengatakannya berkali-kali.",
  str_homestory_N23paixi_90040304_9_dialog_content = "Heheh.",
  str_homestory_N23paixi_90040304_10_dialog_content = "Kamu keren, PlayerName!<sprite=emo_dianzan size=60 />",
  str_homestory_N23paixi_90040305_1_dialog_content = "Jadi, bagaimana hasilnya? Apakah Anda mendapatkan jawaban?",
  str_homestory_N23paixi_90040305_2_dialog_content = "Ya. Sekarang aku tahu bagaimana seorang tentara bayaran yang keren menghabiskan hari mereka.",
  str_homestory_N23paixi_90040305_3_dialog_content = "Heehee, itu bagus.",
  str_homestory_N23paixi_90040305_4_dialog_content = "Sekarang skrip kami akan menjadi lebih baik!",
  str_homestory_N23paixi_90040305_5_dialog_content = "Kami tidak hanya mendapatkan jawaban yang bagus, tetapi kami juga dapat memberikan film ini sentuhan Sadie yang spesial!",
  str_homestory_N23paixi_90040305_6_dialog_content = "Saya kira Anda bisa mengatakannya seperti itu, tetapi saya bertanya-tanya bagaimana film berdasarkan skrip ini akan berubah ...",
  str_homestory_N23paixi_90040305_7_dialog_content = "Saya tidak bisa tidak merasa khawatir.",
  str_homestory_N23paixi_90040305_8_dialog_content = "Nah, ini adalah bagaimana saya memikirkan hal-hal seperti ini.",
  str_homestory_N23paixi_90040305_9_dialog_content = "Tentu, kita semua pemula di sini, tetapi semua \"pro\" juga pernah menjadi pemula. Mereka sampai di tempat mereka sekarang dengan belajar sepanjang jalan, bukan?",
  str_homestory_N23paixi_90040305_10_dialog_content = "Jadi bagaimana jika film ini ternyata buruk? Kami akan belajar dari kesalahan kami dan menjadi lebih baik di lain waktu!",
  str_homestory_N23paixi_90040305_11_dialog_content = "Kau benar sekali, Lilica! Sekarang saya merasa bersemangat!",
  str_homestory_N23paixi_90040305_12_dialog_content = "Kalau begitu, ayo bergerak!",
  str_homestory_N23paixi_90040305_13_dialog_content = "Siap!",
  str_homestory_N23paixi_90040401_1_dialog_content = "PlayerName…",
  str_homestory_N23paixi_90040401_2_dialog_content = "Ada apa, Lilika?",
  str_homestory_N23paixi_90040401_3_dialog_content = "Anda tampaknya sedikit kesal.",
  str_homestory_N23paixi_90040401_4_dialog_content = "Saya khawatir tentang alat peraga yang kita perlukan untuk film.",
  str_homestory_N23paixi_90040401_5_dialog_content = "Maksud Anda alat peraga untuk \"The Swashbuckler\"?",
  str_homestory_N23paixi_90040401_6_dialog_content = "Benar sekali!",
  str_homestory_N23paixi_90040401_7_dialog_content = "Sadie menuntut adegan ini harus \"menyentuh\", jadi semua anggaran masuk ke dalamnya!",
  str_homestory_N23paixi_90040401_8_dialog_content = "Tapi dilihat dari kualitas alat peraga yang kita miliki...",
  str_homestory_N23paixi_90040401_9_dialog_content = "Mereka tidak memenuhi standarnya, bukan?",
  str_homestory_N23paixi_90040401_10_dialog_content = "Bukan hanya standarnya. Mereka bahkan tidak bertemu dengan saya sendiri.",
  str_homestory_N23paixi_90040401_11_dialog_content = "Haruskah aku... bertanya padanya tentang ini?",
  str_homestory_N23paixi_90040401_12_dialog_content = "Maksudku, sebagian besar tuntutannya cenderung abstrak dan tidak benar-benar konkret.<sprite=emo_baiyan size=60 />",
  str_homestory_N23paixi_90040401_13_dialog_content = "Ide bagus!",
  str_homestory_N23paixi_90040401_14_dialog_content = "Terima kasih sebelumnya, PlayerName.",
  str_homestory_N23paixi_90040401_15_dialog_content = "Bukan masalah.",
  str_homestory_N23paixi_90040402_1_dialog_content = "Oh…!",
  str_homestory_N23paixi_90040402_2_dialog_content = "Jadi, Anda hanya perlu saya memberi tahu Anda alat peraga apa yang ada dalam pikiran saya?",
  str_homestory_N23paixi_90040402_3_dialog_content = "Ya. Cobalah untuk detail dan spesifik.",
  str_homestory_N23paixi_90040402_4_dialog_content = "Dalam adegan ini, swashbuckler melihat ke dalam <color=#FFB400>cermin</color> dan mengungkapkan keprihatinan dan kesulitannya.",
  str_homestory_N23paixi_90040402_5_dialog_content = "Dan kemudian datanglah klimaks dari film— sang jagoan berubah!<sprite=emo_nuhuo size=60 />",
  str_homestory_N23paixi_90040402_6_dialog_content = "Cermin tiba-tiba memancarkan cahaya pelangi yang bersinar, dan bintang-bintang emas berkilau dan hati merah muda muncul di sekitarnya!",
  str_homestory_N23paixi_90040402_7_dialog_content = "Sebaiknya kita bisa memutar kamera 360 derajat di sekitar swashbuckler, dengan close-up swashbuckler untuk menunjukkan bahwa dia sudah dewasa!",
  str_homestory_N23paixi_90040402_8_dialog_content = "Ya, ya! Dan begitu dia memutuskan apa yang harus dilakukan, dia mendapatkan kekuatan sihir misterius yang mengubahnya menjadi wanita cantik dan kuat!",
  str_homestory_N23paixi_90040402_9_dialog_content = "... Bukankah ini yang mereka sebut transformasi gadis penyihir? Hal seperti apa yang hanya terjadi di komik fantasi anak-anak?",
  str_homestory_N23paixi_90040402_10_dialog_content = "T-Itu tidak akan berhasil?",
  str_homestory_N23paixi_90040402_11_dialog_content = "Aku... Maksudku, itu tidak bisa dibatalkan.",
  str_homestory_N23paixi_90040402_12_dialog_content = "Ngomong-ngomong, jadi yang kamu butuhkan hanyalah cermin dengan kekuatan magis itu, kan?",
  str_homestory_N23paixi_90040402_13_dialog_content = "Benar.",
  str_homestory_N23paixi_90040402_14_dialog_content = "Nah, kalau begitu... kita mungkin bisa membuat bingkai cermin dari kayu.",
  str_homestory_N23paixi_90040402_15_dialog_content = "Iya!",
  str_homestory_N23paixi_90040402_16_dialog_content = "Hmm, baiklah.",
  str_homestory_N23paixi_90040402_17_dialog_content = "Bagaimanapun, aku akan pergi <color=#FFB400>mengumpulkan beberapa kayu</color> pertama...",
  str_homestory_N23paixi_90040402_18_dialog_content = "Membuat bingkai cermin sepertinya cukup mudah.",
  str_homestory_N23paixi_90040402_19_dialog_content = "Iya!",
  str_homestory_N23paixi_90040402_20_dialog_content = "Ah, seharusnya aku tidak mengatakan itu.",
  str_homestory_N23paixi_90040402_21_dialog_content = "Saya harus mengatakan: Terima kasih, PlayerName!",
  str_homestory_N23paixi_90040402_22_dialog_content = "Bawakan saja kayunya. Saya bisa membuat bingkai sendiri!",
  str_homestory_N23paixi_90040402_23_dialog_content = "Oke.",
  str_homestory_N23paixi_90040403_1_dialog_content = "Kamu sangat cepat, PlayerName.",
  str_homestory_N23paixi_90040403_2_dialog_content = "Semua selesai. ({1}/{2})",
  str_homestory_N23paixi_90040403_5_dialog_content = "Wow! Kamu sangat keren, PlayerName!",
  str_homestory_N23paixi_90040403_6_dialog_content = "Bisakah Anda benar-benar membuat cermin dari kayu?",
  str_homestory_N23paixi_90040403_7_dialog_content = "Apakah Anda membutuhkan bantuan saya?",
  str_homestory_N23paixi_90040403_8_dialog_content = "Percayalah padaku. Aku bisa melakukan itu.",
  str_homestory_N23paixi_90040403_9_dialog_content = "Saya pikir kita akan membutuhkan beberapa bijih.",
  str_homestory_N23paixi_90040403_10_dialog_content = "Benar... Anda hanya bisa membuat rangka dasar dari kayu.",
  str_homestory_N23paixi_90040403_11_dialog_content = "Kita akan membutuhkan <color=#FFB400>bijih</color> untuk membuat cermin yang sebenarnya.",
  str_homestory_N23paixi_90040403_12_dialog_content = "Bingo!",
  str_homestory_N23paixi_90040403_13_dialog_content = "Baik. Aku akan pergi <color=#FFB400>mengumpulkan beberapa bijih</color>, kemudian.",
  str_homestory_N23paixi_90040403_14_dialog_content = "Tidak perlu memaksakan diri, kau dengar? Kita bisa membuat cermin bersama saat aku kembali.",
  str_homestory_N23paixi_90040403_15_dialog_content = "Akan kuatasi!",
  str_homestory_N23paixi_90040403_3_dialog_content = "Hanya sedikit lagi.",
  str_homestory_N23paixi_90040403_4_dialog_content = "Aku akan menunggu!",
  str_homestory_N23paixi_90040404_1_dialog_content = "Kamu sangat cepat, PlayerName.",
  str_homestory_N23paixi_90040404_2_dialog_content = "Semua selesai. ({1}/{2})",
  str_homestory_N23paixi_90040404_5_dialog_content = "Wow! Kamu sangat keren, PlayerName!",
  str_homestory_N23paixi_90040404_6_dialog_content = "Sekarang kami memiliki semua yang kami butuhkan. Saya senang.",
  str_homestory_N23paixi_90040404_7_dialog_content = "Berikan aku waktu, PlayerName. Saya pasti akan membuat Anda terpesona dengan karya saya.",
  str_homestory_N23paixi_90040404_8_dialog_content = "Anda benar-benar tidak membutuhkan bantuan saya?",
  str_homestory_N23paixi_90040404_9_dialog_content = "Anda... benar-benar tahu cara membuat cermin?",
  str_homestory_N23paixi_90040404_10_dialog_content = "Saya pernah menerima pekerjaan seperti ini sebelumnya. Saya harus membongkar 31 cermin.<sprite=emo_mojing size=60 />",
  str_homestory_N23paixi_90040404_11_dialog_content = "Aku bisa melakukan ini!",
  str_homestory_N23paixi_90040404_12_dialog_content = "Baiklah... Jika Anda bersikeras.",
  str_homestory_N23paixi_90040404_13_dialog_content = "Pergilah, PlayerName! Tinggalkan saya untuk pekerjaan saya!",
  str_homestory_N23paixi_90040404_14_dialog_content = "Baiklah…",
  str_homestory_N23paixi_90040404_3_dialog_content = "Hanya sedikit lagi.",
  str_homestory_N23paixi_90040404_4_dialog_content = "Aku akan menunggu!",
  str_homestory_N23paixi_90040405_1_dialog_content = "Hehe. PlayerName!",
  str_homestory_N23paixi_90040405_2_dialog_content = "Hei, Sadi!",
  str_homestory_N23paixi_90040405_3_dialog_content = "Bagaimana perkembangannya?",
  str_homestory_N23paixi_90040405_4_dialog_content = "Jangan khawatir. Saya hanya ingin melihat apakah Anda membutuhkan bantuan.",
  str_homestory_N23paixi_90040405_5_dialog_content = "Saya sudah selesai membuat cermin ajaib!",
  str_homestory_N23paixi_90040405_6_dialog_content = "Anda akan melihatnya sebentar lagi.",
  str_homestory_N23paixi_90040405_7_dialog_content = "Betulkah? Jadi di mana itu?",
  str_homestory_N23paixi_90040405_8_dialog_content = "Itu di kamarku. Saya harus memolesnya terlebih dahulu sebelum saya bisa menunjukkannya kepada Anda.",
  str_homestory_N23paixi_90040405_9_dialog_content = "Yang perlu Anda lakukan hanyalah menunggu!",
  str_homestory_N23paixi_90040405_10_dialog_content = "Betulkah? Kau lebih mampu dari yang kubayangkan, Sadie.",
  str_homestory_N23paixi_90040405_11_dialog_content = "Hei!",
  str_homestory_N23paixi_90040405_12_dialog_content = "Ahem, maksudku, kamu benar-benar mampu!",
  str_homestory_N23paixi_90040405_13_dialog_content = "Itu lebih baik.",
  str_homestory_N23paixi_90040406_1_dialog_content = "Halooooo PlayerName!",
  str_homestory_N23paixi_90040406_2_dialog_content = "Apakah Anda mendapatkan penyangga? Apakah Anda melakukannya?",
  str_homestory_N23paixi_90040406_3_dialog_content = "Aku mendapatkannya mendapatkannya mendapatkannya.",
  str_homestory_N23paixi_90040406_4_dialog_content = "Jadi, apa yang ada dalam pikiran Sadie untuk adegan \"menyentuh\" itu?",
  str_homestory_N23paixi_90040406_5_dialog_content = "Saya sangat penasaran!",
  str_homestory_N23paixi_90040406_6_dialog_content = "Ternyata, hal yang terus dia bicarakan adalah cermin.",
  str_homestory_N23paixi_90040406_7_dialog_content = "Sebuah cermin?",
  str_homestory_N23paixi_90040406_8_dialog_content = "Ya. Sejujurnya, aku tidak bisa membayangkan benar-benar memotret adegan yang ada dalam pikirannya, tapi...",
  str_homestory_N23paixi_90040406_9_dialog_content = "Seperti yang Anda katakan, tidak ada salahnya untuk mencobanya.",
  str_homestory_N23paixi_90040406_10_dialog_content = "Iya!",
  str_homestory_N23paixi_90040406_11_dialog_content = "Jadi, apakah Anda siap?",
  str_homestory_N23paixi_90040406_12_dialog_content = "Kita bisa mulai syuting film pertama studio kita!",
  str_homestory_N23paixi_90040406_13_dialog_content = "Ya, saya siap!",
  str_homestory_N23paixi_90040406_14_dialog_content = "Baik! Kemudian...",
  str_homestory_N23paixi_90040406_15_dialog_content = "Sekarang kami memiliki set, alat peraga, dan peralatan kami ...",
  str_homestory_N23paixi_90040406_16_dialog_content = "Kami akan menebus semua kekurangan kami dengan semangat kami!",
  str_homestory_N23paixi_90040406_17_dialog_content = "Dan sekarang, mari kita tampilkan pemeran utama wanita kita! Sadie, si Pecundang!",
  str_homestory_N23paixi_90040406_18_dialog_content = "Siap! Semua orang di posisi?",
  str_homestory_N23paixi_90040406_19_dialog_content = "Bersiap.",
  str_homestory_N23paixi_90040406_20_dialog_content = "Sekarang, tindakan!<sprite=emo_laba size=60 />",
  str_homestory_N23paixi_90040406_21_dialog_content = "Cerita...",
  str_homestory_N23paixi_90040406_22_dialog_content = "dimulai pada malam yang dingin dan gelap gulita...",
  str_homestory_N23paixi_90040501_1_dialog_content = "PlayerName! Waktu yang tepat! Saya memiliki sesuatu yang ingin saya tanyakan kepada Anda!",
  str_homestory_N23paixi_90040501_2_dialog_content = "Ada apa?",
  str_homestory_N23paixi_90040501_3_dialog_content = "Anda tahu bagaimana kami baru saja menyelesaikan syuting The Swashbuckler?",
  str_homestory_N23paixi_90040501_4_dialog_content = "Apakah sesuatu terjadi? Kami sudah selesai syuting...",
  str_homestory_N23paixi_90040501_5_dialog_content = "Oh! Sama sekali tidak. Filmnya sudah selesai. Ini bukan tentang itu!",
  str_homestory_N23paixi_90040501_6_dialog_content = "Fiuh, itu melegakan.",
  str_homestory_N23paixi_90040501_7_dialog_content = "Ada gadis yang lebih tua ini. Maksudku, dia tidak setua itu, tapi setidaknya lebih tua dariku.",
  str_homestory_N23paixi_90040501_8_dialog_content = "Dia berkeliaran di studio akhir-akhir ini.",
  str_homestory_N23paixi_90040501_9_dialog_content = "Tetapi setiap kali saya bermaksud mendekatinya dan menanyakan apakah dia ingin membuat film,",
  str_homestory_N23paixi_90040501_10_dialog_content = "Aku merasakan aura dingin ini memancar darinya dan itu membuatku takut.",
  str_homestory_N23paixi_90040501_11_dialog_content = "Melihat! Itu dia!",
  str_homestory_N23paixi_90040501_12_dialog_content = "Oh itu <color=#FFB400>Paloma</color>.",
  str_homestory_N23paixi_90040501_13_dialog_content = "Paloma. Entah kenapa, nama itu terdengar familiar.<sprite=emo_yaosu size=60 />",
  str_homestory_N23paixi_90040501_14_dialog_content = "Yah, mungkin karena dia juga tinggal di Umbraton untuk sementara waktu?",
  str_homestory_N23paixi_90040501_15_dialog_content = "Tetapi banyak orang tinggal di Umbraton.",
  str_homestory_N23paixi_90040501_16_dialog_content = "Haha, kurasa kau benar.",
  str_homestory_N23paixi_90040501_17_dialog_content = "Hmph! Anda hanya mengatakan apa pun, bukan, PlayerName?",
  str_homestory_N23paixi_90040501_18_dialog_content = "Mengapa Anda tidak ke sana dan bertanya mengapa dia berkeliaran di studio!",
  str_homestory_N23paixi_90040501_19_dialog_content = "Instingku memberitahuku bahwa dia ingin membuat film tapi tidak tahu bagaimana memberitahu kami.",
  str_homestory_N23paixi_90040501_20_dialog_content = "Hmm, aku akan pergi mencari tahu.",
  str_homestory_N23paixi_90040502_1_dialog_content = "PlayerName.",
  str_homestory_N23paixi_90040502_2_dialog_content = "Hei, Paloma.",
  str_homestory_N23paixi_90040502_3_dialog_content = "Hai.<sprite=emo_baiyan size=60 />",
  str_homestory_N23paixi_90040502_4_dialog_content = "Hmm... Ehem!",
  str_homestory_N23paixi_90040502_5_dialog_content = "Apakah Anda... mengembangkan minat di studio film akhir-akhir ini?",
  str_homestory_N23paixi_90040502_6_dialog_content = "Ya. Saya mendengar bahwa Anda dapat menembak apa pun yang Anda inginkan di sini.",
  str_homestory_N23paixi_90040502_7_dialog_content = "Benar sekali!",
  str_homestory_N23paixi_90040502_8_dialog_content = "Entah itu dokumenter tentang pengalaman Anda, atau mimpi yang ingin Anda wujudkan, atau cerita orang lain...",
  str_homestory_N23paixi_90040502_9_dialog_content = "Peralatan di studio kami dapat membantu Anda merekam apa pun!",
  str_homestory_N23paixi_90040502_10_dialog_content = "Apa yang harus saya lakukan?",
  str_homestory_N23paixi_90040502_11_dialog_content = "Hah?",
  str_homestory_N23paixi_90040502_12_dialog_content = "Katakanlah saya ingin menggunakan peralatan di sini untuk mendokumentasikan hal-hal yang terjadi dalam kehidupan nyata dan mengubahnya menjadi sebuah film—",
  str_homestory_N23paixi_90040502_13_dialog_content = "Pokoknya, menjadi sesuatu yang berfungsi sebagai dokumentasi hidup.",
  str_homestory_N23paixi_90040502_14_dialog_content = "Jika saya ingin melakukan itu, apa yang harus saya berikan? Apa yang kamu mau dari saya?",
  str_homestory_N23paixi_90040502_15_dialog_content = "Saya tidak bisa membayangkan bahwa Anda menjalankan amal di sini.",
  str_homestory_N23paixi_90040502_16_dialog_content = "Ahem. Nah, jika Anda bertanya kepada saya berapa biayanya... Gratis.",
  str_homestory_N23paixi_90040502_17_dialog_content = "Untuk saat ini, setidaknya!",
  str_homestory_N23paixi_90040502_18_dialog_content = "Adapun masa depan...",
  str_homestory_N23paixi_90040502_19_dialog_content = "Kami akan memutuskan apakah kami ingin menagih di luar Cloud Gardens setelah kami menangani operasinya...",
  str_homestory_N23paixi_90040502_20_dialog_content = "Mm... kita akan memikirkan hal itu nanti.",
  str_homestory_N23paixi_90040502_21_dialog_content = "Yang harus Anda ketahui adalah bahwa untuk saat ini, studio kami gratis!",
  str_homestory_N23paixi_90040502_22_dialog_content = "Oh?",
  str_homestory_N23paixi_90040502_23_dialog_content = "Sederhananya, jika ada film yang ingin Anda buat, Anda tinggal menyerahkan naskah dan alat peraganya kepada kami.",
  str_homestory_N23paixi_90040502_24_dialog_content = "Tentu saja, jika Anda tidak memiliki alat peraga yang diperlukan, saya dapat membantu mengumpulkan bahan untuk membuatnya.",
  str_homestory_N23paixi_90040502_25_dialog_content = "Atau, jika Anda tidak tahu cara menulis skrip ... Saya juga dapat mencoba ...",
  str_homestory_N23paixi_90040502_26_dialog_content = "Anda tahu ... membantu mengumpulkan beberapa inspirasi ... atau sesuatu.",
  str_homestory_N23paixi_90040502_27_dialog_content = "Maksudmu aku tidak perlu mengangkat jari?",
  str_homestory_N23paixi_90040502_28_dialog_content = "A-Apakah itu yang baru saja saya katakan?",
  str_homestory_N23paixi_90040502_29_dialog_content = "Bukankah itu yang Anda katakan pada dasarnya?",
  str_homestory_N23paixi_90040502_30_dialog_content = "Aku…",
  str_homestory_N23paixi_90040502_31_dialog_content = "Aku bercanda.",
  str_homestory_N23paixi_90040502_32_dialog_content = "Aku... benar-benar tidak tahu dari keseriusan di wajahmu.",
  str_homestory_N23paixi_90040502_33_dialog_content = "Saya sudah menyiapkan naskah.",
  str_homestory_N23paixi_90040502_34_dialog_content = "Apa yang saya butuhkan adalah inspirasi, lebih disukai hal-hal yang benar untuk hidup dan dapat dipercaya.",
  str_homestory_N23paixi_90040502_35_dialog_content = "Sebenarnya, film yang ingin saya buat... harus seperti film dokumenter.",
  str_homestory_N23paixi_90040502_36_dialog_content = "Sebuah film dokumenter?",
  str_homestory_N23paixi_90040502_37_dialog_content = "Ya.",
  str_homestory_N23paixi_90040502_38_dialog_content = "Oh, begitu…",
  str_homestory_N23paixi_90040502_39_dialog_content = "Baiklah, aku mengerti.",
  str_homestory_N23paixi_90040502_40_dialog_content = "Jangan khawatir. Saya telah melakukan ini sebelumnya!",
  str_homestory_N23paixi_90040502_41_dialog_content = "Jadi, kehidupan sehari-hari siapa yang Anda ingin saya teliti sebagai inspirasi Anda?",
  str_homestory_N23paixi_90040502_42_dialog_content = "<color=#FFB400>Sikare.</color>",
  str_homestory_N23paixi_90040502_43_dialog_content = "... S-Sikare!?",
  str_homestory_N23paixi_90040502_44_dialog_content = "Apakah ada masalah? Orang-orang dari profesi yang berbeda pasti menjalani kehidupan yang berbeda.",
  str_homestory_N23paixi_90040502_45_dialog_content = "T-Tidak masalah...",
  str_homestory_N23paixi_90040502_46_dialog_content = "Dan jelas, Anda lebih dekat dengannya daripada saya.",
  str_homestory_N23paixi_90040502_47_dialog_content = "Itu sebabnya Anda lebih baik untuk pekerjaan itu.",
  str_homestory_N23paixi_90040502_48_dialog_content = "Baiklah, aku mengerti.",
  str_homestory_N23paixi_90040502_49_dialog_content = "Terima kasih.",
  str_homestory_N23paixi_90040502_50_dialog_content = "Aku akan menunggu di sini.",
  str_homestory_N23paixi_90040503_1_dialog_content = "Semakin bertambah?",
  str_homestory_N23paixi_90040503_2_dialog_content = "Hei, Sikare.",
  str_homestory_N23paixi_90040503_3_dialog_content = "Lama tak jumpa.",
  str_homestory_N23paixi_90040503_4_dialog_content = "Kehidupan paramecia yang konyol tapi bahagia itu juga menimpamu, ya?",
  str_homestory_N23paixi_90040503_5_dialog_content = "Aku…",
  str_homestory_N23paixi_90040503_6_dialog_content = "Saya tidak tahu bagaimana menanggapinya.",
  str_homestory_N23paixi_90040503_7_dialog_content = "Saya mengerti. Anda berbagi \"ikatan persahabatan\" dengan mereka.",
  str_homestory_N23paixi_90040503_8_dialog_content = "Jadi, kenapa kau di sini?",
  str_homestory_N23paixi_90040503_9_dialog_content = "Bola salju, kamu benar-benar istimewa, tidak seperti yang lain.",
  str_homestory_N23paixi_90040503_10_dialog_content = "Saya tidak punya keinginan untuk berbicara dengan mereka sama sekali. Aku tidak tahan dengan bau paramecia pada mereka.",
  str_homestory_N23paixi_90040503_11_dialog_content = "Benar... Biarkan aku jujur, Sikare.",
  str_homestory_N23paixi_90040503_12_dialog_content = "Paloma ingin saya bertanya seperti apa kehidupan Anda sehari-hari.",
  str_homestory_N23paixi_90040503_13_dialog_content = "Tolong jangan salah paham! Dia hanya ingin membuat film dokumenter tentang kehidupan sehari-hari semua jenis orang.",
  str_homestory_N23paixi_90040503_14_dialog_content = "Jadi... dia memintaku untuk mencari tahu tentang milikmu.",
  str_homestory_N23paixi_90040503_15_dialog_content = "Paloma... Aku tahu siapa dia.",
  str_homestory_N23paixi_90040503_16_dialog_content = "Kami sudah bertemu. Padahal hanya beberapa kali.",
  str_homestory_N23paixi_90040503_17_dialog_content = "Sepertinya dia hanya sedikit lebih pintar dari paramecia lainnya.",
  str_homestory_N23paixi_90040503_18_dialog_content = "Paling tidak, dia cukup pintar untuk mengetahui bahwa dia akan mendapatkan jawabannya jika dia mengirimmu.",
  str_homestory_N23paixi_90040503_19_dialog_content = "Tapi ingat ini, Bola Salju.",
  str_homestory_N23paixi_90040503_20_dialog_content = "Satu-satunya alasan saya menjawab pertanyaannya adalah karena Andalah yang bertanya kepada saya.",
  str_homestory_N23paixi_90040503_21_dialog_content = "Benar. Terima kasih, Sikare.",
  str_homestory_N23paixi_90040503_22_dialog_content = "Saya memulai hari-hari saya dengan mengobrol dengan Faria.",
  str_homestory_N23paixi_90040503_23_dialog_content = "Jika saya dalam suasana hati yang baik, saya tidak melakukan apa-apa selain menatap langit yang damai.<sprite=emo_pugongying size=60 />",
  str_homestory_N23paixi_90040503_24_dialog_content = "Jika aku sedang dalam suasana hati yang buruk... maka langit di sini tidak bisa memuaskanku.",
  str_homestory_N23paixi_90040503_25_dialog_content = "Lalu aku pergi ke tempat asalku dan memberitahu Faria tentang cerita yang kudengar.",
  str_homestory_N23paixi_90040503_26_dialog_content = "Tentang dunia luar, tentang langit yang berubah warna, tentang pepohonan yang menggugurkan daunnya, dan...",
  str_homestory_N23paixi_90040503_27_dialog_content = "Orang-orang yang berjalan di bumi.",
  str_homestory_N23paixi_90040503_28_dialog_content = "Seperti itulah hari-hariku.",
  str_homestory_N23paixi_90040503_29_dialog_content = "Saya pasti akan memberi tahu Paloma.",
  str_homestory_N23paixi_90040503_30_dialog_content = "Saya pikir dia akan puas dengan jawaban ini.",
  str_homestory_N23paixi_90040503_31_dialog_content = "Hah?",
  str_homestory_N23paixi_90040503_32_dialog_content = "Kau tidak akan memberiku tatapan menyedihkan yang sama seperti yang dilakukan paramecia lainnya?",
  str_homestory_N23paixi_90040503_33_dialog_content = "Aku tidak akan melihatmu seperti itu.",
  str_homestory_N23paixi_90040503_34_dialog_content = "Mengutip Paloma...",
  str_homestory_N23paixi_90040503_35_dialog_content = "\"Orang-orang dari profesi yang berbeda pasti menjalani kehidupan yang berbeda.\"",
  str_homestory_N23paixi_90040503_36_dialog_content = "Jadi, jika seperti ini hari Anda dan jika Anda tidak dapat mengubahnya, maka saya berharap Anda bahagia setiap hari.",
  str_homestory_N23paixi_90040503_37_dialog_content = "...",
  str_homestory_N23paixi_90040503_38_dialog_content = "Kamu pasti berbeda dari yang lain, Snowball.",
  str_homestory_N23paixi_90040504_1_dialog_content = "PlayerName.",
  str_homestory_N23paixi_90040504_2_dialog_content = "Hm...",
  str_homestory_N23paixi_90040504_3_dialog_content = "...",
  str_homestory_N23paixi_90040504_4_dialog_content = "... Jadi seperti itulah hari-hari Sikare.",
  str_homestory_N23paixi_90040504_5_dialog_content = "Aku tahu.",
  str_homestory_N23paixi_90040504_6_dialog_content = "Terima kasih telah membantu saya dalam penelitian.",
  str_homestory_N23paixi_90040504_7_dialog_content = "Saya pasti akan menggunakannya dalam skrip saya.",
  str_homestory_N23paixi_90040504_8_dialog_content = "Anda akan memilikinya segera, bersama dengan alat peraga yang telah saya siapkan.",
  str_homestory_N23paixi_90040504_9_dialog_content = "Oke.",
  str_homestory_N23paixi_90040504_10_dialog_content = "Dan setelah itu... Aku akan meninggalkan dokumenterku di tanganmu yang cakap.",
  str_homestory_N23paixi_90040504_11_dialog_content = "Benar! Tidak masalah!",
  str_homestory_N23paixi_90040504_12_dialog_content = "Terima kasih, PlayerName.",
  str_homestory_N23paixi_90040505_1_dialog_content = "Hai, PlayerName. Bagaimana hasilnya?",
  str_homestory_N23paixi_90040505_2_dialog_content = "Nah, Anda benar.",
  str_homestory_N23paixi_90040505_3_dialog_content = "Paloma memang ingin membuat film.",
  str_homestory_N23paixi_90040505_4_dialog_content = "Tapi dia membutuhkan bahan inspirasi khusus, jadi saya membantunya.",
  str_homestory_N23paixi_90040505_5_dialog_content = "Wow!",
  str_homestory_N23paixi_90040505_6_dialog_content = "Tapi semua itu sudah selesai sekarang!",
  str_homestory_N23paixi_90040505_7_dialog_content = "Skripsinya juga sudah selesai.",
  str_homestory_N23paixi_90040505_8_dialog_content = "Dia bahkan mengatakan bahwa dia akan memberi kita alat peraga.",
  str_homestory_N23paixi_90040505_9_dialog_content = "Wow!!",
  str_homestory_N23paixi_90040505_10_dialog_content = "Dia pasti kaya!<sprite=emo_baiyebi size=60 />",
  str_homestory_N23paixi_90040505_11_dialog_content = "Saya tidak begitu tahu tentang itu.",
  str_homestory_N23paixi_90040505_12_dialog_content = "Tapi dia tidak bisa lebih miskin dari kami berdua.",
  str_homestory_N23paixi_90040505_13_dialog_content = "Saya sangat cemburu!",
  str_homestory_N23paixi_90040505_14_dialog_content = "Yah, bagaimanapun, saya semua bersemangat sekarang!",
  str_homestory_N23paixi_90040505_15_dialog_content = "Saya akan memperoleh semua jenis keterampilan dan menghasilkan banyak uang dengan kemampuan saya sendiri!",
  str_homestory_N23paixi_90040505_16_dialog_content = "PlayerName, mari kita putar kamera setelah kita mendapatkan alat peraga.",
  str_homestory_N23paixi_90040505_17_dialog_content = "Siap!",
  str_homestory_N23paixi_90040601_1_dialog_content = "Temanku tersayang!",
  str_homestory_N23paixi_90040601_2_dialog_content = "Charon!",
  str_homestory_N23paixi_90040601_3_dialog_content = "Anda juga ingin membuat film?",
  str_homestory_N23paixi_90040601_4_dialog_content = "Sebuah film?",
  str_homestory_N23paixi_90040601_5_dialog_content = "Tidak tidak tidak, PlayerName.",
  str_homestory_N23paixi_90040601_6_dialog_content = "Saya hanya mengagumi pemutar rekaman di sini.<sprite=emo_yinfu size=60 />",
  str_homestory_N23paixi_90040601_7_dialog_content = "Benar. Saya ingat Anda adalah penggemar itu.",
  str_homestory_N23paixi_90040601_8_dialog_content = "Satu kali.",
  str_homestory_N23paixi_90040601_9_dialog_content = "Saya pernah menganggap pemutar rekaman itu sebagai barang favorit saya di dunia!",
  str_homestory_N23paixi_90040601_10_dialog_content = "Hah?",
  str_homestory_N23paixi_90040601_11_dialog_content = "Tunggu. Apakah itu berarti Anda telah jatuh cinta dengan pemutar rekaman lain?",
  str_homestory_N23paixi_90040601_12_dialog_content = "Tidak sama sekali, teman baikku.",
  str_homestory_N23paixi_90040601_13_dialog_content = "Saya adalah orang yang sangat setia.",
  str_homestory_N23paixi_90040601_14_dialog_content = "Yang mengatakan, saya percaya bahwa pemutar rekaman dapat menggunakan beberapa perbaikan.",
  str_homestory_N23paixi_90040601_15_dialog_content = "Apa maksudmu?",
  str_homestory_N23paixi_90040601_16_dialog_content = "Anda telah membangun pusat seni baru di sini. Struktur menawan itu hampir tidak bisa lepas dari pandanganku.",
  str_homestory_N23paixi_90040601_17_dialog_content = "Tapi itu membuat saya berpikir tentang karya seni lain di Cloud Gardens—yaitu pemutar rekaman. Itu benar-benar bisa menggunakan pembaruan.",
  str_homestory_N23paixi_90040601_18_dialog_content = "Oh! Musik dan film!",
  str_homestory_N23paixi_90040601_19_dialog_content = "Hanya ketika mereka digabungkan, mereka dapat menghiasi tempat ini dengan cahaya paling glamor!",
  str_homestory_N23paixi_90040601_20_dialog_content = "Uhm... Oke, aku bisa melihat alasanmu di balik itu.",
  str_homestory_N23paixi_90040601_21_dialog_content = "Tapi saya tidak begitu tahu banyak tentang musik. Menurut Anda bagaimana kita harus meningkatkan pemutar rekaman?",
  str_homestory_N23paixi_90040601_22_dialog_content = "Sahabatku, tidak ada yang lebih menyenangkan bagiku daripada menjawab pertanyaanmu ini.",
  str_homestory_N23paixi_90040601_23_dialog_content = "Penyesuaian dapat dilakukan untuk membuat roda penggeraknya bekerja lebih tepat, membuat suara musik menjadi lebih baik...",
  str_homestory_N23paixi_90040601_24_dialog_content = "Oh, memikirkannya saja sudah membuatku bersemangat!<sprite=emo_aixin size=60 />",
  str_homestory_N23paixi_90040601_25_dialog_content = "Apakah Anda akan menjelaskan lebih lanjut tentang itu?",
  str_homestory_N23paixi_90040601_26_dialog_content = "Saya melihat Anda sama bersemangatnya dengan saya!",
  str_homestory_N23paixi_90040601_27_dialog_content = "Bagus! Kalau begitu jangan buang waktu lagi!",
  str_homestory_N23paixi_90040601_28_dialog_content = "Tentu saja, Anda dapat menyerahkan penyesuaian kepada saya.",
  str_homestory_N23paixi_90040601_29_dialog_content = "Tapi aku akan membutuhkanmu untuk mengurus sesuatu yang kecil.",
  str_homestory_N23paixi_90040601_30_dialog_content = "Pertama, saya perlu air.",
  str_homestory_N23paixi_90040601_31_dialog_content = "Kita harus <color=#FFB400>merapikan lingkungan pemutar rekaman</color>.",
  str_homestory_N23paixi_90040601_32_dialog_content = "Dengan begitu, ia bisa kembali ke dirinya yang dulu berseri-seri dalam pelukan lingkungan yang bersih.",
  str_homestory_N23paixi_90040601_33_dialog_content = "Tentu, bukan masalah.",
  str_homestory_N23paixi_90040601_34_dialog_content = "Kemudian, saya akan meluangkan waktu untuk mempelajari pemutar rekaman yang indah itu ...",
  str_homestory_N23paixi_90040601_35_dialog_content = "dan merenungkan bagaimana membuatnya lebih bersinar.",
  str_homestory_N23paixi_90040602_1_dialog_content = "Saya tahu Anda tidak akan pernah mengecewakan artis.",
  str_homestory_N23paixi_90040602_2_dialog_content = "Betul sekali. ({1}/{2})",
  str_homestory_N23paixi_90040602_5_dialog_content = "Bagus.",
  str_homestory_N23paixi_90040602_6_dialog_content = "Sekarang kami memiliki air, kami dapat merapikan lingkungan pemutar rekaman.",
  str_homestory_N23paixi_90040602_7_dialog_content = "Iya!",
  str_homestory_N23paixi_90040602_8_dialog_content = "Saya akan mengambil area luar. Saya akan meninggalkan area dekat pemutar rekaman untuk Anda, oke?",
  str_homestory_N23paixi_90040602_9_dialog_content = "Sebenarnya, mengapa Anda tidak menyerahkan semua pembersihan kepada saya, teman tersayang?",
  str_homestory_N23paixi_90040602_10_dialog_content = "Hah? Kenapa?",
  str_homestory_N23paixi_90040602_11_dialog_content = "Saya percaya pemutar rekaman membutuhkan beberapa pemolesan agar dapat memancarkan semua keindahannya yang memikat dan glamor.",
  str_homestory_N23paixi_90040602_12_dialog_content = "Saya pikir kita akan membutuhkan beberapa <color=#FFB400>bijih</color>.",
  str_homestory_N23paixi_90040602_13_dialog_content = "Anda ingin memoles pemutar rekaman dengan bijih?",
  str_homestory_N23paixi_90040602_14_dialog_content = "Itu benar, teman baikku.",
  str_homestory_N23paixi_90040602_15_dialog_content = "Saya tidak tahu apa yang Anda pikirkan, tetapi sekali lagi, saya juga tidak dapat menemukan kesalahan apa pun.",
  str_homestory_N23paixi_90040602_16_dialog_content = "Oh saya berjanji, Anda akan mengerti setelah Anda melihat hasilnya.",
  str_homestory_N23paixi_90040602_17_dialog_content = "Baiklah. Saya percaya kamu.",
  str_homestory_N23paixi_90040602_18_dialog_content = "Lingkungan sekitar pemutar rekaman telah dibersihkan... tetapi masih jauh dari cukup!",
  str_homestory_N23paixi_90040602_19_dialog_content = "Masih jauh dari pencapaian tujuan akhir yang cemerlang.",
  str_homestory_N23paixi_90040602_20_dialog_content = "Yap.",
  str_homestory_N23paixi_90040602_3_dialog_content = "Sebentar...",
  str_homestory_N23paixi_90040602_4_dialog_content = "Benar. Kalau begitu, saya akan menunggu di sini untuk mengantisipasi sedikit lebih lama.",
  str_homestory_N23paixi_90040603_1_dialog_content = "Saya tahu Anda tidak akan mengecewakan artis.",
  str_homestory_N23paixi_90040603_2_dialog_content = "Betul sekali. ({1}/{2})",
  str_homestory_N23paixi_90040603_5_dialog_content = "Bagus.",
  str_homestory_N23paixi_90040603_6_dialog_content = "Semua bahan sudah siap!",
  str_homestory_N23paixi_90040603_7_dialog_content = "Teman tersayang, saya harus berterima kasih banyak untuk mendukung impian saya.",
  str_homestory_N23paixi_90040603_8_dialog_content = "Diakah itu?",
  str_homestory_N23paixi_90040603_9_dialog_content = "Ya.",
  str_homestory_N23paixi_90040603_10_dialog_content = "Sementara Anda sibuk membantu saya mencapai impian saya, saya menemukan cara untuk memperbarui pemutar rekaman yang indah itu.",
  str_homestory_N23paixi_90040603_11_dialog_content = "Yang harus Anda lakukan sekarang adalah menunggu.",
  str_homestory_N23paixi_90040603_12_dialog_content = "Baiklah kalau begitu.",
  str_homestory_N23paixi_90040603_13_dialog_content = "Terima kasih, Charon!",
  str_homestory_N23paixi_90040603_14_dialog_content = "Akulah yang seharusnya berterima kasih padamu.",
  str_homestory_N23paixi_90040603_3_dialog_content = "Tunggu dulu...",
  str_homestory_N23paixi_90040603_4_dialog_content = "Ah, kalau begitu, saya akan menunggu di sini untuk mengantisipasi sedikit lebih lama.",
  str_homestory_N23paixi_90040604_1_dialog_content = "Wah, PlayerName!",
  str_homestory_N23paixi_90040604_2_dialog_content = "Banyak orang Aurorian telah mengunjungi studio film kami!",
  str_homestory_N23paixi_90040604_3_dialog_content = "Ya! Wakil, apakah Anda melihat film yang mereka buat?",
  str_homestory_N23paixi_90040604_4_dialog_content = "Tunggu. Maksudmu mereka tidak hanya berkeliling di tempat itu, tapi mereka benar-benar membuat film?",
  str_homestory_N23paixi_90040604_5_dialog_content = "Benar sekali!",
  str_homestory_N23paixi_90040604_6_dialog_content = "Itu luar biasa, PlayerName!",
  str_homestory_N23paixi_90040604_7_dialog_content = "Ha ha ha. Yah, itu ide Anda, jadi saya tidak bisa mengambil semua pujian.",
  str_homestory_N23paixi_90040604_8_dialog_content = "Agak egois untuk memuji diri sendiri, tetapi saya masih harus mengatakan: Lihat, saya sudah bilang begitu!",
  str_homestory_N23paixi_90040604_9_dialog_content = "Setiap orang memiliki pengalaman yang ingin mereka dokumentasikan secara visual!",
  str_homestory_N23paixi_90040604_10_dialog_content = "Kau benar.",
  str_homestory_N23paixi_90040604_11_dialog_content = "Ah, tapi dengan catatan itu...",
  str_homestory_N23paixi_90040604_12_dialog_content = "Anda sudah bekerja keras, bukan?",
  str_homestory_N23paixi_90040604_13_dialog_content = "Aku bisa menebak.",
  str_homestory_N23paixi_90040604_14_dialog_content = "Pasti kerja keras untuk membuat studio film berdiri dan berjalan dari keadaan awalnya.",
  str_homestory_N23paixi_90040604_15_dialog_content = "Ha! Yah, yang saya lakukan hanyalah mengumpulkan bahan dan menjalankan beberapa tugas.",
  str_homestory_N23paixi_90040604_16_dialog_content = "Minos, Lilica, Hedy, Sadie, Paloma, dan Charon menangani sebagian besar hal teknis.",
  str_homestory_N23paixi_90040604_17_dialog_content = "Semua orang luar biasa!",
  str_homestory_N23paixi_90040604_18_dialog_content = "Jadi PlayerName, apakah kamu sudah melihat semua film yang mereka buat?",
  str_homestory_N23paixi_90040604_19_dialog_content = "Tidak secara keseluruhan, tidak.",
  str_homestory_N23paixi_90040604_20_dialog_content = "Maksudku, aku tahu tentang film mereka, tapi...",
  str_homestory_N23paixi_90040604_21_dialog_content = "Saya tidak punya kesempatan untuk melihat bagaimana mereka berubah.",
  str_homestory_N23paixi_90040604_22_dialog_content = "Sehat! Inilah kesempatan Anda!",
  str_homestory_N23paixi_90040604_23_dialog_content = "Bagaimana kalau kita pergi menonton mereka bersama?",
  str_homestory_N23paixi_90040604_24_dialog_content = "Oke!"
}
return config
